gsap_scrolltrigger.codesnippet:
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

// Basic scroll-triggered animation
gsap.to('.box', {
  scrollTrigger: {
    trigger: '.box',
    start: 'top center',
    end: 'bottom top',
    scrub: 1,
    pin: true,
    markers: false
  },
  x: 500,
  rotation: 360
});

// Timeline pinned section (storytelling scroll)
const tl = gsap.timeline({
  scrollTrigger: {
    trigger: '.section',
    start: 'top top',
    end: '+=1000',
    scrub: true,
    pin: true
  }
});
tl.to('.title', { opacity: 1, y: 0 })
  .to('.image', { scale: 1.2 })
  .to('.text', { opacity: 1 });

// Horizontal scroll
gsap.to('.wrapper', {
  xPercent: -100,
  scrollTrigger: {
    trigger: '.container',
    pin: true,
    scrub: true,
    end: '+=1000'
  }
});

// Callbacks
ScrollTrigger.create({
  trigger: '.element',
  start: 'top 80%',
  onEnter: ({ progress, direction, isActive }) => console.log('entered'),
  onLeave: () => console.log('left'),
  onEnterBack: () => console.log('entered back'),
  onUpdate: self => console.log('progress:', self.progress)
});

lenis.codesnippet:
import Lenis from 'lenis';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

// Basic Lenis setup
const lenis = new Lenis({
  duration: 1.2,        // scroll duration multiplier
  easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
  orientation: 'vertical',
  gestureOrientation: 'vertical',
  smoothWheel: true,
  wheelMultiplier: 1,
  touchMultiplier: 2,
  infinite: false
});

// Standalone RAF loop
function raf(time) {
  lenis.raf(time);
  requestAnimationFrame(raf);
}
requestAnimationFrame(raf);

// GSAP ScrollTrigger integration (recommended)
lenis.on('scroll', ScrollTrigger.update);
gsap.ticker.add((time) => {
  lenis.raf(time * 1000);
});
gsap.ticker.lagSmoothing(0);

// Listen to scroll events
lenis.on('scroll', (e) => {
  console.log(e.scroll, e.progress, e.velocity, e.direction);
});

// Control methods
lenis.stop();     // pause scrolling
lenis.start();    // resume scrolling
lenis.scrollTo('#target', { offset: -100, duration: 2 });

// Required CSS
