import('@dimforge/rapier3d-compat').then(RAPIER => {
  RAPIER.init().then(() => {

    // 1. Create world with gravity
    const gravity = { x: 0.0, y: -9.81, z: 0.0 };
    const world = new RAPIER.World(gravity);

    // 2. Static ground collider (no rigid body = fixed)
    const groundDesc = RAPIER.ColliderDesc.cuboid(10.0, 0.1, 10.0);
    world.createCollider(groundDesc);

    // 3. Dynamic rigid body
    const rigidBodyDesc = RAPIER.RigidBodyDesc.dynamic()
      .setTranslation(0.0, 5.0, 0.0)
      .setLinearDamping(0.5)
      .setGravityScale(1.0);
    const rigidBody = world.createRigidBody(rigidBodyDesc);

    // 4. Attach collider to rigid body
    const colliderDesc = RAPIER.ColliderDesc.cuboid(0.5, 0.5, 0.5)
      .setFriction(0.8)
      .setRestitution(0.3)
      .setDensity(1.0);
    world.createCollider(colliderDesc, rigidBody);

    // 5. Three.js mesh (separate from physics body)
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({ color: 0xff6600 })
    );
    scene.add(mesh);

    // 6. Sync loop — copy physics position to mesh every frame
    function animate() {
      world.step(); // advance physics
      const pos = rigidBody.translation();
      const rot = rigidBody.rotation();
      mesh.position.set(pos.x, pos.y, pos.z);
      mesh.quaternion.set(rot.x, rot.y, rot.z, rot.w);
    }

    // Collider shapes: cuboid, ball, capsule, cylinder, trimesh, heightfield
    // Body types: dynamic(), fixed(), kinematicPositionBased(), kinematicVelocityBased()
    // Apply forces: rigidBody.applyImpulse({ x:0, y:10, z:0 }, true);
    // Apply torque:  rigidBody.applyTorqueImpulse({ x:0, y:1, z:0 }, true);
    // Set velocity:  rigidBody.setLinvel({ x:1, y:3, z:0 }, true);
  });
});

