  src: ['sound.webm', 'sound.mp3'],
  volume: 0.5,
  loop: false,
  autoplay: false,
  onend: () => console.log('Finished!')
});
sound.play();
sound.pause();
sound.stop();
sound.fade(0, 1, 2000); // fade from 0 to 1 over 2s

// 3D Positional audio
const spatial = new Howl({
  src: ['ambient.webm', 'ambient.mp3'],
  loop: true,
  volume: 1.0,
  pannerAttr: {
    panningModel: 'HRTF',
    refDistance: 1,
    rolloffFactor: 1,
    distanceModel: 'inverse'
  }
});
spatial.pos(x, y, z);       // set sound position in 3D space
spatial.play();

// Update listener position from Three.js camera each frame
Howler.pos(
  camera.position.x,
  camera.position.y,
  camera.position.z
);
Howler.orientation(
  forward.x, forward.y, forward.z, // look direction
  up.x, up.y, up.z                  // up vector
);

// Audio sprites (multiple sounds in one file)
const sprite = new Howl({
  src: ['sprites.webm', 'sprites.mp3'],
  sprite: {
    footstep: [0, 350],
    jump:     [500, 300],
    land:     [1000, 450]
  }
});
