import CustomShaderMaterial from 'three-custom-shader-material/vanilla';
import { MeshStandardMaterial } from 'three';

const material = new CustomShaderMaterial({
  baseMaterial: MeshStandardMaterial,
  vertexShader: `
    uniform float uTime;
    void main() {
      vec3 pos = position;
      pos.y += sin(pos.x * 5.0 + uTime) * 0.1;
      csm_Position = pos;
    }
  `,
  fragmentShader: `
    uniform vec3 uColor;
    void main() {
      csm_DiffuseColor = vec4(uColor, 1.0);
    }
  `,
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color('#ff6600') }
  },
  // Standard material props still work
  metalness: 0.5,
  roughness: 0.3
});

