import { getProject, types } from '@theatre/core';
import { SheetProvider, PerspectiveCamera, useCurrentSheet } from '@theatre/r3f';

const project = getProject('My Project');
const sheet = project.sheet('Scene');

function Scene() {
  const sheet = useCurrentSheet();

  // Scroll-driven animation
  useFrame(() => {
    const scroll = window.scrollY / (document.body.scrollHeight - window.innerHeight);
    sheet.sequence.position = scroll * sheet.sequence.length;
  });

  return (
    <SheetProvider sheet={sheet}>
      <PerspectiveCamera theatreKey="Camera" makeDefault />
      {/* Objects with theatreKey are animatable in Theatre.js studio */}
    </SheetProvider>
  );
}

