use_cannon.codesnippet:
import { Physics, useBox, usePlane, useSphere } from '@react-three/cannon';

function PhysicsScene() {
  return (
    <Physics gravity={[0, -9.81, 0]}>
      <Ground />
      <FallingBox />
    </Physics>
  );
}

function Ground() {
  const [ref] = usePlane(() => ({ rotation: [-Math.PI / 2, 0, 0] }));
  return <mesh ref={ref}><planeGeometry args={[100, 100]} /></mesh>;
}

function FallingBox() {
  const [ref, api] = useBox(() => ({
    mass: 1,
    position: [0, 5, 0],
    onCollide: (e) => console.log('Hit!', e.body)
  }));

  // Apply impulse on click
  const jump = () => api.applyImpulse([0, 10, 0], [0, 0, 0]);

  return <mesh ref={ref} onClick={jump}><boxGeometry /></mesh>;
}

